initial begin
$k_error();
end
endmodule

`timescale 1ns/1ns
module top;

initial begin
$display("function %0d",$k_add(20,22));
end
endmodule

`timescale 1ns/1ns
module top;

initial begin
logic [128:0] expected; expected=129'h1000000000000000000000000a9abcdef; expected[29]=1'bx;expected[28]=1'bz;
if($k_wide() === expected) $display("sized ok"); else $display("sized BAD");
end
endmodule

`timescale 1ns/1ns
module top;
logic[128:0] value;
initial begin
logic [128:0] expected; expected=129'h1000000000000000000000000a9abcdef; expected[29]=1'bx;expected[28]=1'bz;
$k_vector(value);if(value===expected)$display("hdl ok");else $display("hdl BAD");
end
endmodule

`timescale 1ns/1ns
module top;
int values[2:0];
initial begin
$k_memory();$display("hdl %0d",values[1]);
end
endmodule

`timescale 1ns/1ns
module top;
real value=1.5;
initial begin
$k_real(value);$display("hdl %.2f",value);
end
endmodule

`timescale 1ns/1ns
module top;
reg[23:0] value="abc";
initial begin
$k_string(value);$display("hdl %s",value);
end
endmodule

`timescale 1ps/1ps
module top;

initial begin
#4294967297;$k_time();
end
endmodule

`timescale 1ns/1ns
module top;
int lifecycle_marker;
initial begin
$k_lifecycle(lifecycle_marker);$display("body");#1;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;

initial begin
$k_after();#3;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;

initial begin
$k_cancel();#3;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;

initial begin
#1;$k_next();#4;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;
int value=0;
initial begin
#1;$k_regions(value);value<=1;$display("active %0d",value);#1;$display("hdl %0d",value);$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;
int value=0;
initial begin
#1;$k_watch(value);#1;value<=1;#1;value<=2;#1;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;
int value=0;
initial begin
#1;$k_watch(value);$k_put_trace(value);#1;$finish(0);
end
endmodule

`timescale 1ns/1ns
module top;
int value=0;
initial begin
$k_delayed(value);#1;$display("before %0d",value);#2;$display("after %0d",value);
end
endmodule

`timescale 1ns/1ns
module top;
reg value=0;
initial begin
#1;$k_force(value);value=0;$display("forced %0d",value);$k_release(value);$display("released %0d",value);value=0;$display("assigned %0d",value);
end
endmodule
